// Cursos por género: construir una canción completa desde cero, paso a paso, como en una clase de producción.
// Cada curso: ritmo → bajo → armonía → melodía → arreglo → mezcla. Cada paso añade pistas que suenan bien
// con los samples de Dirt-Samples y los sintetizadores del estudio, y Maestro explica el porqué musical.
//
// Los patrones son reconstrucciones propias de ritmos tradicionales (un ritmo no tiene autor), escritos para este
// estudio. Las fuentes de cada curso son lecturas recomendadas, no copias. Ver docs/COURSES.md.
import { L } from "./i18n.js";

const T = (id, es, en, kind, code) => ({ id, nombre: L(es, en), tipo: kind, codigo: code });
const P = (fragmento, es, en) => ({ fragmento, explicacion: L(es, en) });
const S = (label, url) => ({ label, url });
// Los cursos latinos se basan en una skill del plugin music-composition (se carga sola al preguntar a Maestro)
const PLUGIN = "https://github.com/vsalesa/music-composition-skills/tree/main/plugins/music-composition/skills/";
// Un baterista real tocando el estilo (Groove MIDI Dataset de Google Magenta, CC BY 4.0). El estudio baja el MIDI
// y lo convierte en pistas que conservan la fuerza y el tiempo de cada golpe. sounds cambia los sonidos de la batería
// por los del curso; slow estira el compás cuando el tempo del curso cuenta distinto.
const GMD = (file, start, style, note, extra = {}) => ({ file, start, bars: 4, style, note, ...extra });
// La forma de la canción (0.17): [nombre es, nombre en, compases]. Va a la partitura como secciones (marcas de ensayo).
const F = (...xs) => xs.map(([es, en, n]) => ({ name: L(es, en), bars: n }));
const SK = (name) => ({ label: L(`Skill del plugin · ${name}`, `Plugin skill · ${name}`), url: PLUGIN + name, skill: true });

// Explicaciones comunes de los pasos de arreglo y mezcla
const ARR_PARTS = () => [
  P('mask "<f!4 t!12>"', "Una máscara por compases: f = calla, t = suena. «f!4» es f repetido 4 veces. Cada compás es un ciclo de Tidal.", "A bar-by-bar mask: f = silent, t = plays. «f!4» is f repeated 4 times. Each bar is one Tidal cycle."),
  P("$", "El $ separa la transformación (la máscara) de lo que suena. Todo lo que hay a la derecha pasa por la máscara.", "The $ separates the transformation (the mask) from what plays. Everything to its right goes through the mask."),
  P(L("pestaña Arreglo", "Arrangement tab"), "Puedes ver y cambiar estas máscaras como una rejilla de casillas en la pestaña Arreglo.", "You can see and change these masks as a grid of boxes in the Arrangement tab."),
];
const MIX_PARTS = () => [
  P("# amp", "El volumen de cada pista, en dB en la mesa de mezcla. 0 dB es el volumen normal, −6 dB es más o menos la mitad de fuerte.", "Each track's volume, in dB on the mixing desk. 0 dB is normal volume, −6 dB is roughly half as loud."),
  P("# eqlow / eqmid / eqhigh", "El ecualizador: graves (200 Hz), medios (1 kHz) y agudos (4 kHz). Sirve para que cada instrumento tenga su sitio.", "The equaliser: lows (200 Hz), mids (1 kHz) and highs (4 kHz). It gives each instrument its own space."),
  P(L("pestaña Mezcla", "Mix tab"), "No cambia el código de tus pistas: se añade al final cuando suenan. Mueve los deslizadores y escucha.", "It doesn't change your track code: it's added at the end when they play. Move the sliders and listen."),
];

