        arrange: { d1: "f!4 t!12", d2: "f!4 t!12", d3: "f!2 t!14", d4: "f!8 t!8", d5: "f!4 t!12", d6: "t!16", d7: "t!4 f!4 t!8" },
        parts: ARR_PARTS(),
