        listen: L("La caja tiene que «cortar».", "The snare has to «cut through»."),
        mix: { d1: { vol: 0, low: 2 }, d2: { vol: 0 }, d3: { vol: -7 }, d4: { vol: -8 }, d5: { vol: -1 }, d6: { vol: -7, low: -4 }, d7: { vol: -4 } },
        parts: MIX_PARTS(),
