export const courseById = (id) => COURSES.find((c) => c.id === id);

// El curso con su variante aplicada (0.17: variantes de cumbia). Sin variante, la primera (o el curso tal cual).
export function courseFor(id, variant) {
  const c = courseById(id);
  if (!c || !c.variants) return c;
  const v = c.variants.find((x) => x.id === variant) || c.variants[0];
  if (!v.steps && !v.bpm && !v.tradition) return { ...c, variant: v };
  const steps = c.steps.map((s, i) => (v.steps && v.steps[i] ? { ...s, ...v.steps[i] } : s));
  return { ...c, variant: v, bpm: v.bpm || c.bpm, tradition: v.tradition || c.tradition, lens: v.lens || c.lens, steps };
}

// Los sonidos que usa un curso (para avisar de los que aún no suenan)
export function courseSounds(c) {
  const out = new Set();
  for (const s of c.steps) for (const t of s.tracks || []) {
    for (const m of t.codigo.matchAll(/(?:^|[\s(#$])(?:s|sound)\s+"([^"]*)"/g)) for (const w of m[1].match(/[A-Za-z][\w.]*/g) || []) out.add(w);
  }
  return [...out];
}

// Lo que suena al terminar el curso (todas las pistas en su última versión, sin máscaras), para «Escuchar el resultado»
export function finalTracks(course) {
  const out = new Map();
  for (const s of course.steps) for (const t of s.tracks || []) out.set(t.id, t);
  return [...out.values()];
}

// "f!4 t!12" → [false×4, true×12]
export function maskArr(str) {
  const out = [];
  for (const tok of str.trim().split(/\s+/)) {
    const m = tok.match(/^([tf])(?:!(\d+))?$/);
    if (!m) continue;
    for (let i = 0; i < (m[2] ? +m[2] : 1); i++) out.push(m[1] === "t");
  }
  return out;
}

// Progreso por curso en este navegador: { merengue: [0,1,2], … }
const KEY = "tidal-studio-courses-v1";
export function courseProgress() { try { return JSON.parse(localStorage.getItem(KEY)) || {}; } catch { return {}; } }
export function markStepDone(id, i) {
  const p = courseProgress();
  p[id] = [...new Set([...(p[id] || []), i])].sort((a, b) => a - b);
  try { localStorage.setItem(KEY, JSON.stringify(p)); } catch {}
}
